head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f0eee6" value="#f0eee6"/><Variable name="page.text" description="Text color" type="color" default="#272b21" value="#272b21"/><Variable name="theme.accent" description="Accent color" type="color" default="#626746" value="#626746"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Italiana', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.site-header{padding:28px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #bec0b1}.brand{letter-spacing:5px;font-size:19px}nav{display:flex;gap:28px;font-size:10px;text-transform:uppercase;letter-spacing:1px}.fashion-hero{position:relative;display:grid;grid-template-columns:1fr 1.05fr;gap:0;padding:55px 5% 70px;min-height:700px}.smallcaps{font-size:9px;letter-spacing:2px;text-transform:uppercase}.fashion-title{z-index:1;padding-top:30px}.fashion-title h1{font:normal clamp(75px,10vw,139px)/.9 'Italiana', Georgia,serif;letter-spacing:-7px;margin:50px -100px 32px 0}.fashion-title p:last-child{font-size:13px;line-height:1.7}.fashion-hero figure{margin:0}.fashion-hero svg{width:100%;display:block}.fashion-hero figcaption{font-size:8px;letter-spacing:1.8px;margin-top:13px;text-align:right}.fashion-feature{position:absolute;bottom:40px;left:24%;background:#626746;color:#f8f5e9;width:285px;padding:32px}.fashion-feature span{font-size:9px;letter-spacing:2px}.fashion-feature h2{font:normal 33px/1.05 'Italiana', Georgia,serif}.fashion-feature p{font-size:12px;line-height:1.8}.fashion-manifesto{padding:70px 15% 80px;text-align:center;border-bottom:1px solid #bec0b1}.fashion-manifesto h2{font:normal clamp(43px,5vw,65px)/1.08 'Italiana', Georgia,serif;letter-spacing:-2px;margin:32px 0}.fashion-manifesto>p:last-child{max-width:420px;margin:auto;font-size:14px;line-height:1.9}.fashion-index{padding:60px 10%}.fashion-index>a{display:flex;align-items:center;gap:35px;border-bottom:1px solid #bec0b1;padding:15px 0}.fashion-index>a span{font-size:10px}.fashion-index h3{font:normal 35px 'Italiana', Georgia,serif;margin:15px 0}.fashion-index b{margin-left:auto;font-weight:400;font-size:24px}.latest{padding:30px 5% 70px}.section-heading{font:italic 35px 'Italiana', Georgia,serif;margin-bottom:35px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:34px}.post-card:nth-child(2){padding-top:65px}.post-media{aspect-ratio:3/4;object-fit:cover;background:#d4d0c3}.post-meta{font-size:9px;letter-spacing:1.2px;text-transform:uppercase}.post-title{font:normal 29px/1.14 'Italiana', Georgia,serif}.post-excerpt{font-size:12px;line-height:1.8}.fashion-closing{padding:60px 10%;background:#282d23;color:#f0eee6}.fashion-closing h2{font:normal 65px/1 'Italiana', Georgia,serif;letter-spacing:-3px}.fashion-closing a{font-size:11px;border-bottom:1px solid;padding-bottom:5px}.site-footer{padding:38px 5%;display:flex;justify-content:space-between;gap:24px;font-size:10px}.site-footer strong{letter-spacing:2px}a{transition:opacity .25s}a:hover,a:focus-visible{opacity:.72}@media(max-width:700px){.site-header{flex-direction:column;gap:22px}.fashion-hero{grid-template-columns:1fr;padding-top:30px}.fashion-title h1{font-size:82px;letter-spacing:-4px;margin:30px 0}.fashion-hero figure{margin-top:20px}.fashion-feature{position:relative;left:auto;bottom:auto;width:auto;margin:-20px 20px 0;z-index:2}.fashion-manifesto{padding:45px 7%}.fashion-index{padding:45px 5%}.fashion-index h3{font-size:26px}.posts-grid{grid-template-columns:1fr}.post-card:nth-child(2){padding-top:0}.post-media{max-height:400px;width:100%}.fashion-closing h2{font-size:48px}.site-footer{flex-direction:column}}
:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,svg{max-width:100%}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
h1,h2,h3{font-family:'Italiana', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
